## Task 2 — Skill-Boundary Hardening

**What**: Add four reliability rails: 120s timeout, structured error envelope, job-state TTL, frontend max-retries.
**Why**: Each rail closes a distinct failure path; all four together make the boundary fail predictably.
**Effort**: 1 day | **Parallel with**: Tasks 1 and 3

### Files to Touch

| File | Action |
|------|--------|
| `api/modules/ai/routes/actions.py` | Timeout ceiling + error envelope |
| Job-state module (wherever the job dict lives) | TTL expiry |
| Polling Angular component | Max-retries + user-visible error state |

### Rail 1 — 120 s Timeout Ceiling

Wrap every `chain.run(...)` call in `actions.py`:

```python
import concurrent.futures

SKILL_TIMEOUT_SECONDS = 120

class SkillTimeoutError(Exception):
    pass

def _run_skill_with_timeout(skill_fn, *args, **kwargs):
    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
        future = executor.submit(skill_fn, *args, **kwargs)
        try:
            return future.result(timeout=SKILL_TIMEOUT_SECONDS)
        except concurrent.futures.TimeoutError:
            raise SkillTimeoutError(f"Skill exceeded {SKILL_TIMEOUT_SECONDS}s ceiling")
```

### Rail 2 — Structured Error Envelope

Every failure path in `actions.py` must return `{"error": "..."}` with status 500.
The four cases to handle:

| Failure | Catch | Response |
|---------|-------|----------|
| `SkillTimeoutError` | `except SkillTimeoutError` | `{"error": "Skill timed out after 120s"}`, 500 |
| Missing `text` key | `if "text" not in result` | `{"error": "Skill returned unexpected output shape"}`, 500 |
| Bad JSON | `except (json.JSONDecodeError, ValueError)` | `{"error": "Skill returned malformed JSON"}`, 500 |
| Unhandled exception | `except Exception as e` (outermost) | `{"error": str(e)}`, 500 |

Always call `app.logger.exception(...)` before returning the envelope in the catch-all.

Pattern for each route:
```python
@actions_bp.route("/some-action", methods=["POST"])
def some_action():
    try:
        result = _run_skill_with_timeout(run_skill, skill_name, payload)
        if "text" not in result:
            return jsonify({"error": "Skill returned unexpected output shape"}), 500
        return jsonify(result), 200
    except SkillTimeoutError:
        return jsonify({"error": "Skill timed out after 120s"}), 500
    except Exception as e:
        app.logger.exception("Unhandled skill error")
        return jsonify({"error": str(e)}), 500
```

### Rail 3 — Job-State TTL

```python
import threading, time

_jobs: dict = {}
_lock = threading.Lock()
JOB_TTL_SECONDS = 3600

def set_job(job_id: str, state: dict) -> None:
    with _lock:
        _jobs[job_id] = {**state, "_created_at": time.monotonic()}

def get_job(job_id: str) -> dict | None:
    with _lock:
        job = _jobs.get(job_id)
        if job is None:
            return None
        if time.monotonic() - job["_created_at"] > JOB_TTL_SECONDS:
            del _jobs[job_id]
            return None
        return {k: v for k, v in job.items() if k != "_created_at"}
```

Expiry is opportunistic on read — no new thread required.

### Rail 4 — Frontend Max-Retries

```typescript
private readonly POLL_MAX_RETRIES = 30;   // 30 × 2 s ≈ 60 s
private readonly POLL_INTERVAL_MS  = 2000;
private pollRetries = 0;
private pollIntervalId: ReturnType<typeof setInterval> | null = null;
pollingError: string | null = null;

startPolling(jobId: string): void {
  this.pollRetries = 0;
  this.pollingError = null;
  this.pollIntervalId = setInterval(() => {
    this.pollRetries++;
    if (this.pollRetries > this.POLL_MAX_RETRIES) {
      this.stopPolling();
      this.pollingError = 'Generation is taking too long. Please try again.';
      return;
    }
    this.jobService.getStatus(jobId).subscribe({
      next: (s) => { if (s.done) { this.stopPolling(); this.handleSuccess(s); }
                     else if (s.error) { this.stopPolling(); this.pollingError = s.error; } },
      error: () => { this.stopPolling(); this.pollingError = 'Could not reach the server.'; }
    });
  }, this.POLL_INTERVAL_MS);
}

stopPolling(): void {
  if (this.pollIntervalId !== null) { clearInterval(this.pollIntervalId); this.pollIntervalId = null; }
}

ngOnDestroy(): void { this.stopPolling(); }
```

Add to the component template:
```html
<div *ngIf="pollingError" data-test="polling-error" class="error-state">
  {{ pollingError }}
</div>
```

### Acceptance Checklist
- [ ] Every action route enforces 120s ceiling; timeout returns `{"error": "..."}` + 500
- [ ] Missing `text`, bad JSON, and unhandled exceptions all return the envelope; no traceback in the response body
- [ ] `get_job()` returns `None` for entries older than `JOB_TTL_SECONDS`
- [ ] Polling stops after `POLL_MAX_RETRIES`; `[data-test="polling-error"]` is visible
- [ ] `clearInterval` is called in `ngOnDestroy`

