def get_registered_routes(app):
    return [r.rule for r in app.url_map.iter_rules()
            if not r.rule.startswith("/static")]

class TestCORSHeaders:
    @pytest.mark.parametrize("route", get_registered_routes(create_app()))
    def test_options_has_cors_header(self, client, route):
        resp = client.options(route)
        assert resp.headers.get("Access-Control-Allow-Origin") is not None

class TestErrorEnvelopeShape:
    @pytest.mark.parametrize("route,method,payload", [
        ("/ai/brainstorm", "POST", {"text": ""}),
        # ... all eight action routes
    ])
    def test_error_is_envelope(self, client, route, method, payload):
        resp = getattr(client, method.lower())(route, json=payload)
        if resp.status_code >= 400:
            data = resp.get_json()
            assert data is not None and "error" in data

class TestOpenAPIResponseShape:
    @pytest.mark.parametrize("route", get_registered_routes(create_app()))
    def test_200_matches_schema(self, client, route, openapi_spec, monkeypatch):
        monkeypatch.setenv("CHAIN_PROVIDER", "mock")
        path_spec = openapi_spec.get("paths", {}).get(route)
        if path_spec is None:
            pytest.skip(f"{route} not in openapi.yaml")
        resp = client.get(route)
        if resp.status_code == 200:
            schema = (path_spec.get("get", {}).get("responses", {})
                      .get("200", {}).get("content", {})
                      .get("application/json", {}).get("schema", {}))
            if schema:
                jsonschema.validate(resp.get_json(), schema)
